// LingoUP Mini App sahifasi
export const APP_HTML = "<!doctype html>\n<html lang=\"uz\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover\">\n<title>LingoUP</title>\n<script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n<style>\n  :root {\n    --bg: var(--tg-theme-bg-color, #ffffff);\n    --bg2: var(--tg-theme-secondary-bg-color, #f2f3f5);\n    --card: var(--tg-theme-section-bg-color, var(--tg-theme-bg-color, #ffffff));\n    --text: var(--tg-theme-text-color, #111418);\n    --hint: var(--tg-theme-hint-color, #8a9099);\n    --link: var(--tg-theme-link-color, #2a7de1);\n    --btn: var(--tg-theme-button-color, #2a7de1);\n    --btn-text: var(--tg-theme-button-text-color, #ffffff);\n    --danger: var(--tg-theme-destructive-text-color, #e5484d);\n    --ok: #2fa24f;\n    --line: color-mix(in srgb, var(--hint) 22%, transparent);\n    --r: 14px;\n  }\n  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n  html, body { margin: 0; background: var(--bg2); color: var(--text);\n    font: 15px/1.4 -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif; }\n  body { padding: 12px 12px calc(90px + env(safe-area-inset-bottom)); }\n  h1 { font-size: 22px; margin: 6px 4px 12px; }\n  .muted { color: var(--hint); font-size: 13px; }\n  .card { background: var(--card); border-radius: var(--r); padding: 12px; margin-bottom: 10px; }\n  .row { display: flex; align-items: center; gap: 8px; }\n  .grow { flex: 1; min-width: 0; }\n  input, textarea, select { width: 100%; font: inherit; color: var(--text); background: var(--bg2);\n    border: 1px solid transparent; border-radius: 10px; padding: 10px 12px; outline: none; }\n  input:focus, textarea:focus, select:focus { border-color: var(--btn); }\n  textarea { resize: vertical; min-height: 44px; }\n  label.f { display: block; font-size: 12px; color: var(--hint); margin: 10px 2px 4px; text-transform: uppercase; letter-spacing: .03em; }\n  button { font: inherit; border: 0; cursor: pointer; border-radius: 10px; }\n  .btn { background: var(--btn); color: var(--btn-text); padding: 10px 14px; font-weight: 600; }\n  .ghost { background: transparent; color: var(--link); padding: 8px 10px; }\n  .icon { background: var(--bg2); color: var(--text); width: 36px; height: 36px; display: grid; place-items: center; flex: none; font-size: 16px; }\n  .icon.del { color: var(--danger); }\n  .item { display: flex; align-items: center; gap: 10px; padding: 12px; background: var(--card); border-radius: var(--r); margin-bottom: 8px; cursor: pointer; }\n  .item .t { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .badge { font-size: 12px; padding: 2px 8px; border-radius: 99px; background: var(--bg2); color: var(--hint); white-space: nowrap; }\n  .q-head { display: flex; align-items: flex-start; gap: 10px; cursor: pointer; }\n  .q-num { flex: none; width: 28px; height: 28px; border-radius: 50%; background: var(--bg2); display: grid; place-items: center; font-size: 13px; font-weight: 600; }\n  .q-text { flex: 1; min-width: 0; word-break: break-word; }\n  .q-ans { color: var(--ok); font-size: 13px; margin-top: 2px; }\n  .q-body { margin-top: 10px; border-top: 1px solid var(--line); padding-top: 4px; }\n  .opt { display: flex; align-items: center; gap: 8px; margin-top: 8px; }\n  .radio { flex: none; width: 26px; height: 26px; border-radius: 50%; border: 2px solid var(--hint); background: transparent; padding: 0; }\n  .radio.on { border-color: var(--ok); background: var(--ok); box-shadow: inset 0 0 0 4px var(--card); }\n  .err { border-color: var(--danger) !important; }\n  .tools { display: flex; gap: 6px; justify-content: flex-end; margin-top: 10px; flex-wrap: wrap; }\n  .empty { text-align: center; padding: 40px 16px; color: var(--hint); }\n  .toast { position: fixed; left: 50%; bottom: calc(24px + env(safe-area-inset-bottom)); transform: translateX(-50%); background: #222; color: #fff;\n    padding: 10px 16px; border-radius: 12px; font-size: 14px; opacity: 0; transition: opacity .2s; pointer-events: none; max-width: 90%; text-align: center; z-index: 9; }\n  .toast.show { opacity: .95; }\n  .seg { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }\n  .spin { width: 28px; height: 28px; border: 3px solid var(--line); border-top-color: var(--btn); border-radius: 50%; animation: s 0.8s linear infinite; margin: 40px auto; }\n  @keyframes s { to { transform: rotate(360deg); } }\n  .img-note { font-size: 13px; color: var(--hint); margin-top: 6px; }\n  .tabs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; background: var(--card); border-radius: 12px; padding: 4px; margin-bottom: 10px; position: sticky; top: 0; z-index: 2; }\n  .tabs button { background: transparent; color: var(--hint); padding: 8px 2px; font-size: 13px; font-weight: 600; white-space: nowrap; }\n  .tabs button.on { background: var(--btn); color: var(--btn-text); }\n  .stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 10px; }\n  .stat { background: var(--card); border-radius: var(--r); padding: 12px; }\n  .stat b { display: block; font-size: 22px; font-variant-numeric: tabular-nums; }\n  .bar { display: flex; align-items: center; gap: 8px; margin: 6px 0; font-size: 13px; }\n  .bar .lbl { width: 64px; color: var(--hint); flex: none; }\n  .bar .trk { flex: 1; height: 10px; background: var(--bg2); border-radius: 99px; overflow: hidden; }\n  .bar .fill { height: 100%; background: var(--btn); border-radius: 99px; }\n  .bar .n { width: 30px; text-align: right; font-variant-numeric: tabular-nums; flex: none; }\n  .li { display: flex; gap: 10px; align-items: center; padding: 8px 0; border-top: 1px solid var(--line); }\n  .li:first-of-type { border-top: 0; }\n  .chip { display: inline-block; padding: 8px 12px; margin: 4px 4px 0 0; border-radius: 99px; background: var(--bg2); color: var(--text); font-size: 14px; }\n  .chip.on { background: var(--btn); color: var(--btn-text); }\n  .progress { height: 8px; background: var(--bg2); border-radius: 99px; overflow: hidden; margin: 10px 0 6px; }\n  .progress > div { height: 100%; background: var(--ok); transition: width .4s; }\n  h3 { margin: 0 0 8px; font-size: 15px; }\n  .tabs.two { grid-template-columns: 1fr 1fr; }\n  .sec { margin: 14px 4px 8px; font-weight: 700; color: var(--hint); font-size: 13px; text-transform: uppercase; letter-spacing: .03em; }\n  .hero { text-align: center; padding: 22px 16px; }\n  .hero .big { font-size: 44px; line-height: 1; margin-bottom: 8px; }\n  .hero h2 { margin: 0 0 6px; font-size: 20px; }\n  .meta { display: flex; justify-content: center; gap: 14px; flex-wrap: wrap; color: var(--hint); font-size: 14px; margin-top: 10px; }\n  .playtop { display: flex; align-items: center; gap: 10px; margin: 2px 2px 10px; font-size: 14px; font-weight: 600; }\n  .tbar { height: 6px; background: var(--card); border-radius: 99px; overflow: hidden; margin-bottom: 12px; }\n  .tbar > div { height: 100%; background: var(--btn); }\n  .tbar.low > div { background: var(--danger); }\n  .qbox { background: var(--card); border-radius: var(--r); padding: 18px 16px; font-size: 18px; font-weight: 600; line-height: 1.35; margin-bottom: 12px; word-break: break-word; }\n  .qbox img { display: block; max-width: 100%; max-height: 260px; margin: 0 auto 12px; border-radius: 10px; }\n  .ans { display: block; width: 100%; text-align: left; background: var(--card); color: var(--text); padding: 14px 16px; margin-bottom: 8px;\n    border-radius: 12px; font-size: 16px; border: 2px solid transparent; transition: transform .1s; }\n  .ans:active { transform: scale(.98); }\n  .ans.right { border-color: var(--ok); background: color-mix(in srgb, var(--ok) 14%, var(--card)); }\n  .ans.wrong { border-color: var(--danger); background: color-mix(in srgb, var(--danger) 12%, var(--card)); }\n  .ans:disabled { cursor: default; }\n  .expl { background: var(--card); border-left: 4px solid var(--btn); border-radius: 10px; padding: 10px 12px; font-size: 14px; margin-top: 4px; }\n  .score { font-size: 52px; font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1; }\n  .rgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 10px 0; }\n  .rgrid div { background: var(--card); border-radius: 12px; padding: 10px; text-align: center; font-size: 13px; color: var(--hint); }\n  .rgrid b { display: block; font-size: 20px; color: var(--text); }\n  .pick { display: block; text-align: center; background: var(--btn); color: var(--btn-text); padding: 14px; border-radius: 12px; font-weight: 700; font-size: 16px; cursor: pointer; }\n  .pick.alt { background: var(--bg2); color: var(--text); font-weight: 600; font-size: 14px; margin-top: 8px; padding: 10px; }\n  .pick input { display: none; }\n  .tips { font-size: 13px; color: var(--hint); margin: 10px 0 0; padding-left: 18px; }\n  .tips li { margin: 2px 0; }\n  canvas.prev { width: 100%; border-radius: 10px; display: block; background: #000; }\n  .agrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(56px, 1fr)); gap: 6px; margin-top: 10px; }\n  .agrid button { padding: 6px 2px; background: var(--bg2); color: var(--text); font-size: 13px; border: 2px solid transparent; }\n  .agrid button b { display: block; font-size: 15px; }\n  .agrid button.ok { border-color: var(--ok); }\n  .agrid button.no { border-color: var(--danger); }\n  .agrid button.blank { opacity: .6; }\n</style>\n</head>\n<body>\n<div id=\"app\"><div class=\"spin\"></div></div>\n<div class=\"toast\" id=\"toast\"></div>\n<script>\nconst tg = window.Telegram && Telegram.WebApp;\nif (tg) { tg.ready(); tg.expand(); }\nconst $app = document.getElementById(\"app\");\nconst SHUF = { all: \"Hammasi aralashtiriladi\", none: \"Aralashtirilmaydi\", q: \"Faqat savollar\", a: \"Faqat javoblar\" };\nconst tLabel = (t) => (t < 60 ? t + \" soniya\" : t / 60 + \" daqiqa\");\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\nlet state = { view: \"list\", items: [], total: 0, search: \"\", quiz: null, open: -1, dirty: false };\n\nfunction toast(msg) {\n  const el = document.getElementById(\"toast\");\n  el.textContent = msg; el.classList.add(\"show\");\n  clearTimeout(toast.t); toast.t = setTimeout(() => el.classList.remove(\"show\"), 2600);\n}\nfunction haptic(kind) { try { tg.HapticFeedback.notificationOccurred(kind); } catch (e) {} }\n\nasync function api(path, body) {\n  const r = await fetch(\"/api\" + path, {\n    method: body ? \"POST\" : \"GET\",\n    headers: { \"X-Init-Data\": tg ? tg.initData : \"\", \"content-type\": \"application/json\" },\n    body: body ? JSON.stringify(body) : undefined,\n  });\n  const j = await r.json().catch(() => ({ error: \"Server javob bermadi\" }));\n  if (!r.ok) { const err = new Error(j.error || \"Xatolik\"); err.data = j; throw err; }\n  return j;\n}\n\nfunction confirmBox(text) {\n  return new Promise((res) => { if (tg && tg.showConfirm) tg.showConfirm(text, res); else res(confirm(text)); });\n}\n\n// ---------- Tugmalar (Telegram MainButton / BackButton) ----------\nfunction setMain(text, fn) {\n  if (!tg) return;\n  tg.MainButton.offClick(setMain.fn || (() => {}));\n  if (!text) { tg.MainButton.hide(); return; }\n  setMain.fn = fn;\n  tg.MainButton.setText(text); tg.MainButton.onClick(fn); tg.MainButton.show();\n}\nfunction setBack(fn) {\n  if (!tg) return;\n  tg.BackButton.offClick(setBack.fn || (() => {}));\n  if (!fn) { tg.BackButton.hide(); return; }\n  setBack.fn = fn; tg.BackButton.onClick(fn); tg.BackButton.show();\n}\n\n// ---------- Ro'yxat ----------\nasync function loadList() {\n  state.view = \"list\"; state.quiz = null;\n  setBack(null); setMain(null);\n  state.home = \"mine\";\n  $app.innerHTML = homeTabs() + '<div class=\"spin\"></div>'; bindHome();\n  try {\n    const j = await api(\"/quizzes\" + (state.search ? \"?q=\" + encodeURIComponent(state.search) : \"\"));\n    state.items = j.items; state.total = j.total;\n  } catch (e) { $app.innerHTML = '<div class=\"empty\">⚠️ ' + esc(e.message) + \"</div>\"; return; }\n  renderList();\n}\nfunction renderList() {\n  const list = state.items.map((q) =>\n    '<div class=\"item\" data-id=\"' + esc(q.id) + '\"><div class=\"grow\"><div class=\"t\">' + esc(q.title) + '</div>' +\n    '<div class=\"muted\">🖊 ' + q.count + ' ta savol' + (q.chan ? \" · 📢 kanalda\" : \"\") + (q.public ? \" · 🌐 ochiq\" : \"\") + \"</div></div>\" +\n    (q.pending ? '<span class=\"badge\">⏳ tekshiruvda</span>' : '<span class=\"muted\">›</span>') + \"</div>\").join(\"\");\n  $app.innerHTML = homeTabs() +\n    '<div class=\"card\" style=\"padding:8px\"><input id=\"search\" type=\"search\" placeholder=\"🔎 Test nomi bo\\'yicha qidirish\" value=\"' + esc(state.search) + '\"></div>' +\n    '<div class=\"muted\" style=\"margin:0 4px 8px\">' + (state.search ? \"Topildi: \" + state.items.length : \"Jami: \" + state.total + \" ta test\") + \"</div>\" +\n    (list || '<div class=\"empty\">' + (state.search ? \"Hech narsa topilmadi\" : \"Hali test yo'q.<br>Botga fayl yuborib, birinchi testingizni yarating.\") + \"</div>\");\n  bindHome();\n  const s = document.getElementById(\"search\");\n  s.addEventListener(\"input\", () => { clearTimeout(s.t); s.t = setTimeout(() => { state.search = s.value.trim(); loadList(); }, 400); });\n  $app.querySelectorAll(\".item\").forEach((el) => el.addEventListener(\"click\", () => openQuiz(el.dataset.id)));\n}\n\n// ---------- Tahrirlash ----------\nasync function openQuiz(id) {\n  setBack(goBack); setMain(null);\n  $app.innerHTML = '<div class=\"spin\"></div>';\n  try { state.quiz = await api(\"/quiz?id=\" + encodeURIComponent(id)); }\n  catch (e) { toast(e.message); return loadList(); }\n  state.view = \"edit\"; state.open = -1; state.dirty = false; state.filter = \"\"; state.tab = \"edit\";\n  renderEdit();\n}\nasync function goBack() {\n  if (state.dirty && !(await confirmBox(\"Saqlanmagan o'zgarishlar bor. Chiqib ketaymi?\"))) return;\n  history.replaceState(null, \"\", location.pathname);\n  if (state.quiz && state.quiz.manual) { state.dirty = false; if (tg) tg.disableClosingConfirmation(); return loadNew(); }\n  stopPoll(); loadList();\n}\nfunction markDirty() {\n  if (!state.dirty) { state.dirty = true; setMain(\"💾 Saqlash\", save); if (tg) tg.enableClosingConfirmation(); }\n}\n\nfunction qCard(q, i) {\n  const open = state.open === i;\n  let h = '<div class=\"card\" id=\"q' + i + '\"><div class=\"q-head\" data-tog=\"' + i + '\"><div class=\"q-num\">' + (i + 1) + \"</div>\" +\n    '<div class=\"q-text\">' + (q.img ? \"🖼 \" : \"\") + (esc(q.q) || '<span class=\"muted\">(matnsiz savol)</span>') +\n    '<div class=\"q-ans\">✓ ' + esc(q.opts[q.correct] ?? \"\") + \"</div></div>\" +\n    '<span class=\"muted\">' + (open ? \"▴\" : \"▾\") + \"</span></div>\";\n  if (open) {\n    h += '<div class=\"q-body\"><label class=\"f\">Savol</label><textarea data-f=\"q\" data-i=\"' + i + '\" rows=\"2\" maxlength=\"1000\">' + esc(q.q) + \"</textarea>\";\n    if (q.img) h += '<div class=\"img-note\">🖼 Savolda rasm bor (rasmni botda o\\'zgartirish mumkin)</div>';\n    h += '<label class=\"f\">Variantlar — to\\'g\\'ri javobni belgilang</label>';\n    q.opts.forEach((o, k) => {\n      h += '<div class=\"opt\"><button class=\"radio' + (k === q.correct ? \" on\" : \"\") + '\" data-ok=\"' + i + \":\" + k + '\" aria-label=\"To\\'g\\'ri javob\"></button>' +\n        '<input class=\"grow\" data-o=\"' + i + \":\" + k + '\" value=\"' + esc(o) + '\" maxlength=\"100\" placeholder=\"Variant ' + (k + 1) + '\">' +\n        (q.opts.length > 2 ? '<button class=\"icon del\" data-rmo=\"' + i + \":\" + k + '\" aria-label=\"O\\'chirish\">✕</button>' : \"\") + \"</div>\";\n    });\n    if (q.opts.length < 10) h += '<button class=\"ghost\" data-addo=\"' + i + '\">＋ Variant qo\\'shish</button>';\n    h += '<label class=\"f\">Izoh (ixtiyoriy, 200 belgigacha)</label><textarea data-f=\"exp\" data-i=\"' + i + '\" rows=\"2\" maxlength=\"200\" placeholder=\"Noto\\'g\\'ri javobda ko\\'rsatiladi\">' + esc(q.exp || \"\") + \"</textarea>\";\n    h += '<div class=\"tools\"><button class=\"icon\" data-up=\"' + i + '\" aria-label=\"Yuqoriga\">↑</button><button class=\"icon\" data-down=\"' + i + '\" aria-label=\"Pastga\">↓</button>' +\n      '<button class=\"icon\" data-dup=\"' + i + '\" aria-label=\"Nusxa\">⧉</button><button class=\"icon del\" data-rmq=\"' + i + '\" aria-label=\"Savolni o\\'chirish\">🗑</button></div></div>';\n  }\n  return h + \"</div>\";\n}\n\nconst tabsHtml = () => '<div class=\"tabs\">' + [[\"edit\", \"✏️ Savollar\"], [\"stats\", \"📊 Natija\"], [\"chan\", \"🗳 Kanal\"], [\"omr\", \"📄 Varaq\"]]\n  .map(([k, v]) => '<button data-tab=\"' + k + '\" class=\"' + (state.tab === k ? \"on\" : \"\") + '\">' + v + \"</button>\").join(\"\") + \"</div>\";\nfunction bindTabs() {\n  $app.querySelectorAll(\"[data-tab]\").forEach((b) => b.addEventListener(\"click\", () => {\n    state.tab = b.dataset.tab; stopPoll();\n    if (state.tab === \"edit\") renderEdit(); else if (state.tab === \"stats\") renderStats(); else if (state.tab === \"omr\") renderOmr(); else renderChan();\n    window.scrollTo(0, 0);\n  }));\n}\nfunction renderEdit() {\n  if (state.dirty) setMain(\"💾 Saqlash\", save);\n  const z = state.quiz;\n  const f = state.filter.toLowerCase();\n  const shown = z.questions.map((q, i) => [q, i]).filter(([q]) => !f || (q.q + \" \" + q.opts.join(\" \")).toLowerCase().includes(f));\n  const timers = z.timers.map((t) => '<option value=\"' + t + '\"' + (t === z.timer ? \" selected\" : \"\") + \">\" + tLabel(t) + \"</option>\").join(\"\");\n  const shufs = Object.entries(SHUF).map(([k, v]) => '<option value=\"' + k + '\"' + (k === z.shuffle ? \" selected\" : \"\") + \">\" + v + \"</option>\").join(\"\");\n  $app.innerHTML = (z.manual ? '<h1>✍️ Qo\\'lda test tuzish</h1>' : tabsHtml()) +\n    (z.pending ? '<div class=\"card muted\">⏳ Bu test muallif tekshiruvida.</div>' : \"\") +\n    '<div class=\"card\"><label class=\"f\" style=\"margin-top:0\">Test nomi</label><input id=\"title\" maxlength=\"100\" value=\"' + esc(z.title) + '\">' +\n    '<label class=\"f\">Tavsif</label><textarea id=\"desc\" rows=\"2\" maxlength=\"300\" placeholder=\"Ixtiyoriy\">' + esc(z.description) + \"</textarea>\" +\n    '<div class=\"seg\"><div><label class=\"f\">⏱ Har savolga</label><select id=\"timer\">' + timers + '</select></div>' +\n    '<div><label class=\"f\">🔀 Aralashtirish</label><select id=\"shuf\">' + shufs + \"</select></div></div></div>\" +\n    '<div class=\"row\" style=\"margin:14px 4px 8px\"><b class=\"grow\">Savollar: ' + z.questions.length + \"</b>\" +\n    '<button class=\"ghost\" id=\"addq\">＋ Savol</button></div>' +\n    (z.questions.length > 8 ? '<div class=\"card\" style=\"padding:8px\"><input id=\"qf\" type=\"search\" placeholder=\"🔎 Savollar ichidan qidirish\" value=\"' + esc(state.filter) + '\"></div>' : \"\") +\n    (shown.map(([q, i]) => qCard(q, i)).join(\"\") || '<div class=\"empty\">Savol topilmadi</div>') +\n    (z.manual ? \"\" : '<div class=\"card\" style=\"margin-top:20px\"><button class=\"ghost\" id=\"delquiz\" style=\"color:var(--danger);width:100%\">🗑 Testni o\\'chirish</button></div>');\n  bindEdit(); bindTabs();\n  if (!tg) { const b = document.createElement(\"button\"); b.className = \"btn\"; b.textContent = \"💾 Saqlash\"; b.style.width = \"100%\"; b.onclick = save; $app.appendChild(b); }\n}\n\nfunction bindEdit() {\n  const z = state.quiz;\n  const on = (sel, ev, fn) => $app.querySelectorAll(sel).forEach((el) => el.addEventListener(ev, (e) => fn(el, e)));\n  document.getElementById(\"title\").addEventListener(\"input\", (e) => { z.title = e.target.value; markDirty(); });\n  document.getElementById(\"desc\").addEventListener(\"input\", (e) => { z.description = e.target.value; markDirty(); });\n  document.getElementById(\"timer\").addEventListener(\"change\", (e) => { z.timer = +e.target.value; markDirty(); });\n  document.getElementById(\"shuf\").addEventListener(\"change\", (e) => { z.shuffle = e.target.value; markDirty(); });\n  const qf = document.getElementById(\"qf\");\n  if (qf) qf.addEventListener(\"input\", () => { clearTimeout(qf.t); qf.t = setTimeout(() => { state.filter = qf.value.trim(); renderEdit(); focusEnd(\"qf\"); }, 300); });\n  document.getElementById(\"addq\").addEventListener(\"click\", () => {\n    z.questions.push({ q: \"\", opts: [\"\", \"\"], correct: 0 });\n    state.open = z.questions.length - 1; state.filter = \"\"; markDirty(); renderEdit();\n    const el = document.getElementById(\"q\" + state.open); el.scrollIntoView({ behavior: \"smooth\" }); el.querySelector(\"textarea\").focus();\n  });\n  const dq = document.getElementById(\"delquiz\"); if (dq) dq.addEventListener(\"click\", delQuiz);\n  on(\"[data-tog]\", \"click\", (el) => { const i = +el.dataset.tog; state.open = state.open === i ? -1 : i; renderEdit(); scrollTo(i); });\n  on(\"[data-f]\", \"input\", (el) => { z.questions[+el.dataset.i][el.dataset.f] = el.value; markDirty(); });\n  on(\"[data-o]\", \"input\", (el) => { const [i, k] = el.dataset.o.split(\":\").map(Number); z.questions[i].opts[k] = el.value; markDirty(); });\n  on(\"[data-ok]\", \"click\", (el) => { const [i, k] = el.dataset.ok.split(\":\").map(Number); z.questions[i].correct = k; markDirty(); haptic(\"success\"); renderEdit(); });\n  on(\"[data-addo]\", \"click\", (el) => { const i = +el.dataset.addo; z.questions[i].opts.push(\"\"); markDirty(); renderEdit();\n    const ins = $app.querySelectorAll('[data-o^=\"' + i + ':\"]'); ins[ins.length - 1].focus(); });\n  on(\"[data-rmo]\", \"click\", (el) => { const [i, k] = el.dataset.rmo.split(\":\").map(Number); const q = z.questions[i];\n    q.opts.splice(k, 1); if (q.correct === k) q.correct = 0; else if (q.correct > k) q.correct--; markDirty(); renderEdit(); });\n  on(\"[data-up]\", \"click\", (el) => move(+el.dataset.up, -1));\n  on(\"[data-down]\", \"click\", (el) => move(+el.dataset.down, 1));\n  on(\"[data-dup]\", \"click\", (el) => { const i = +el.dataset.dup; const c = JSON.parse(JSON.stringify(z.questions[i])); delete c.pair;\n    z.questions.splice(i + 1, 0, c); state.open = i + 1; markDirty(); renderEdit(); scrollTo(i + 1); });\n  on(\"[data-rmq]\", \"click\", async (el) => { const i = +el.dataset.rmq;\n    if (z.questions.length === 1) return toast(\"Testda kamida bitta savol qolishi kerak\");\n    if (!(await confirmBox((i + 1) + \"-savolni o'chiraymi?\"))) return;\n    z.questions.splice(i, 1); state.open = -1; markDirty(); renderEdit(); });\n}\nfunction move(i, d) {\n  const z = state.quiz, j = i + d;\n  if (j < 0 || j >= z.questions.length) return;\n  [z.questions[i], z.questions[j]] = [z.questions[j], z.questions[i]];\n  state.open = j; markDirty(); renderEdit(); scrollTo(j);\n}\nfunction scrollTo(i) { const el = document.getElementById(\"q\" + i); if (el) el.scrollIntoView({ block: \"nearest\", behavior: \"smooth\" }); }\nfunction focusEnd(id) { const el = document.getElementById(id); if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }\n\n// Saqlashdan oldin mijoz tomonda tekshirish — xato savolni ochib ko'rsatadi\nfunction validate() {\n  const z = state.quiz;\n  if (!z.title.trim()) return { msg: \"Test nomini yozing\" };\n  for (let i = 0; i < z.questions.length; i++) {\n    const q = z.questions[i];\n    const opts = q.opts.map((o) => o.trim());\n    if (!q.q.trim() && !q.img) return { i, msg: (i + 1) + \"-savol matni bo'sh\" };\n    if (opts.some((o) => !o)) return { i, msg: (i + 1) + \"-savolda bo'sh variant bor\" };\n    if (new Set(opts.map((o) => o.toLowerCase())).size !== opts.length) return { i, msg: (i + 1) + \"-savolda bir xil variantlar bor\" };\n  }\n  return null;\n}\nasync function save() {\n  const bad = validate();\n  if (bad) { haptic(\"error\"); toast(\"⚠️ \" + bad.msg); if (bad.i != null) { state.open = bad.i; state.filter = \"\"; renderEdit(); scrollTo(bad.i); } return; }\n  const z = state.quiz;\n  if (tg) tg.MainButton.showProgress();\n  if (z.manual) {\n    try {\n      const r = await api(\"/createmanual\", { title: z.title, description: z.description, timer: z.timer, shuffle: z.shuffle, questions: z.questions });\n      state.dirty = false; setMain(null); if (tg) { tg.disableClosingConfirmation(); tg.MainButton.hideProgress(); }\n      haptic(\"success\"); return renderMade(r);\n    } catch (e) { haptic(\"error\"); toast(\"⚠️ \" + e.message); if (tg) tg.MainButton.hideProgress(); return; }\n  }\n  try {\n    const r = await api(\"/quiz\", { id: z.id, title: z.title, description: z.description, timer: z.timer, shuffle: z.shuffle, questions: z.questions });\n    state.dirty = false; setMain(null); if (tg) tg.disableClosingConfirmation();\n    haptic(\"success\"); toast(\"✅ Saqlandi — \" + r.count + \" ta savol\");\n  } catch (e) { haptic(\"error\"); toast(\"⚠️ \" + e.message); }\n  finally { if (tg) tg.MainButton.hideProgress(); }\n}\nasync function delQuiz() {\n  if (!(await confirmBox(\"«\" + state.quiz.title + \"» testini butunlay o'chiraymi? Natijalar ham o'chadi.\"))) return;\n  try { await api(\"/delete\", { id: state.quiz.id }); state.dirty = false; if (tg) tg.disableClosingConfirmation(); toast(\"🗑 Test o'chirildi\"); loadList(); }\n  catch (e) { toast(\"⚠️ \" + e.message); }\n}\n\n// ---------- Statistika ----------\nconst fmtT = (s) => (s < 60 ? s + \" son\" : Math.floor(s / 60) + \" daq \" + (s % 60) + \" son\");\nasync function renderStats() {\n  setMain(null);\n  $app.innerHTML = tabsHtml() + '<div class=\"spin\"></div>'; bindTabs();\n  let d;\n  try { d = await api(\"/stats?id=\" + encodeURIComponent(state.quiz.id)); }\n  catch (e) { $app.innerHTML = tabsHtml() + '<div class=\"empty\">⚠️ ' + esc(e.message) + \"</div>\"; bindTabs(); return; }\n  if (state.tab !== \"stats\") return;\n  const max = Math.max(1, ...d.buckets);\n  const labels = [\"0–49%\", \"50–69%\", \"70–89%\", \"90–100%\"];\n  const medals = [\"🥇\", \"🥈\", \"🥉\"];\n  let h = tabsHtml() + '<div class=\"stats\">' +\n    '<div class=\"stat\"><span class=\"muted\">👥 Yechganlar</span><b>' + d.takers + '</b><span class=\"muted\">+' + d.week + \" shu hafta</span></div>\" +\n    '<div class=\"stat\"><span class=\"muted\">🎯 O\\'rtacha natija</span><b>' + d.avg + '%</b><span class=\"muted\">⏱ ' + fmtT(d.avgSecs) + \"</span></div></div>\";\n  if (!d.takers && !d.nGames) h += '<div class=\"empty\">📊 Hali hech kim bu testni yechmagan.<br>Testni ulashing — natijalar shu yerda chiqadi.</div>';\n  else {\n    h += '<div class=\"card\"><h3>Natijalar taqsimoti</h3>' + d.buckets.map((n, i) =>\n      '<div class=\"bar\"><span class=\"lbl\">' + labels[i] + '</span><span class=\"trk\"><span class=\"fill\" style=\"display:block;width:' + Math.round((n / max) * 100) + '%\"></span></span><span class=\"n\">' + n + \"</span></div>\").join(\"\") + \"</div>\";\n    if (d.top.length) h += '<div class=\"card\"><h3>🏆 Reyting</h3>' + d.top.map((r, i) =>\n      '<div class=\"li\"><span style=\"width:26px\">' + (medals[i] || i + 1 + \".\") + '</span><span class=\"grow\">' + esc(r.name) + '</span><b>' + r.ok + \"/\" + r.total + '</b><span class=\"muted\">' + fmtT(r.secs) + \"</span></div>\").join(\"\") + \"</div>\";\n    h += '<div class=\"card\"><h3>❗ Eng ko\\'p xato qilingan savollar</h3>' + (d.hard.length ? d.hard.map((w) =>\n      '<div class=\"li\"><span class=\"grow\"><div>' + esc(w.q) + '</div><div class=\"q-ans\">✓ ' + esc(w.ans) + '</div></span><span class=\"badge\">' +\n      Math.round((w.wrong / w.total) * 100) + \"% xato · \" + w.wrong + \"/\" + w.total + \"</span></div>\").join(\"\")\n      : '<div class=\"muted\">Yangi yechilgan testlardan keyin shu yerda ko\\'rinadi.</div>') + \"</div>\";\n    if (d.nGames) h += '<div class=\"card\"><h3>👥 Guruhlarda o\\'tkazildi: ' + d.nGames + \" marta</h3>\" + d.games.map((g) =>\n      '<div class=\"li\"><span class=\"grow\">' + esc(g.chatTitle || \"Guruh\") + '<div class=\"muted\">' + new Date(g.created).toLocaleDateString(\"uz-UZ\") + \"</div></span>\" +\n      '<span class=\"muted\">' + g.players + \" kishi · \" + g.asked + \" savol</span></div>\").join(\"\") + \"</div>\";\n  }\n  $app.innerHTML = h; bindTabs();\n}\n\n// ---------- Kanalda so'rovnoma ----------\nconst STEPS = [[0, \"⚡️ Ketma-ket\"], [60, \"1 daq\"], [300, \"5 daq\"], [900, \"15 daq\"], [1800, \"30 daq\"], [3600, \"1 soat\"]];\nfunction stopPoll() { clearInterval(state.poll); state.poll = null; }\nasync function renderChan() {\n  setMain(null);\n  state.cp = state.cp || { interval: 0, limit: 0, chat: null };\n  $app.innerHTML = tabsHtml() + '<div class=\"spin\"></div>'; bindTabs();\n  try { state.channels = (await api(\"/channels\")).items; } catch (e) { state.channels = []; }\n  if (state.tab !== \"chan\") return;\n  if (!state.cp.chat && state.channels.length) state.cp.chat = state.channels[0].id;\n  drawChan();\n  if (state.cp.chat) checkJob();\n}\nfunction drawChan(job) {\n  const cp = state.cp, n = state.quiz.questions.length;\n  let h = tabsHtml();\n  if (job && !job.busy) {\n    const pct = Math.round((job.sent / job.total) * 100);\n    h += '<div class=\"card\"><h3>' + (job.stopped ? \"⏹ To\\'xtatilmoqda…\" : \"🚀 Joylanmoqda\") + \"</h3>\" +\n      '<div>«' + esc(job.title) + '» → <b>' + esc(job.chatTitle) + \"</b></div>\" +\n      '<div class=\"progress\"><div style=\"width:' + pct + '%\"></div></div><div class=\"muted\">' + job.sent + \" / \" + job.total + \" savol joylandi</div>\" +\n      (job.stopped ? \"\" : '<button class=\"btn\" id=\"cpstop\" style=\"width:100%;margin-top:12px;background:var(--danger)\">⏹ To\\'xtatish</button>') + \"</div>\";\n    $app.innerHTML = h; bindTabs();\n    const b = document.getElementById(\"cpstop\");\n    if (b) b.onclick = async () => { if (!(await confirmBox(\"Joylashni to'xtataymi?\"))) return; await api(\"/cpstop\", { id: state.quiz.id, chat: cp.chat }).catch(() => {}); checkJob(); };\n    return;\n  }\n  h += '<div class=\"card\"><h3>📢 Kanal</h3>' +\n    (state.channels.length ? state.channels.map((c) => '<button class=\"chip' + (String(c.id) === String(cp.chat) ? \" on\" : \"\") + '\" data-ch=\"' + c.id + '\">' + esc(c.title) + \"</button>\").join(\"\") : \"\") +\n    '<div class=\"row\" style=\"margin-top:10px\"><input class=\"grow\" id=\"newch\" placeholder=\"@kanal_manzili\"><button class=\"btn\" id=\"addch\">Qo\\'shish</button></div>' +\n    '<div class=\"muted\" style=\"margin-top:8px\">Botni kanalga admin qiling va «Xabar joylash» huquqini bering.</div></div>';\n  if (job && job.busy) h += '<div class=\"card muted\">⏳ Bu kanalda hozir boshqa so\\'rovnoma joylanmoqda.</div>';\n  h += '<div class=\"card\"><h3>⏳ Savollar orasidagi vaqt</h3>' + STEPS.map(([v, l]) => '<button class=\"chip' + (cp.interval === v ? \" on\" : \"\") + '\" data-iv=\"' + v + '\">' + l + \"</button>\").join(\"\") + \"</div>\" +\n    '<div class=\"card\"><h3>🖊 Nechta savol</h3>' + [0, 10, 20, 30, 50].filter((v) => v < n).map((v) =>\n      '<button class=\"chip' + (cp.limit === v ? \" on\" : \"\") + '\" data-lim=\"' + v + '\">' + (v ? v + \" ta\" : \"Hammasi (\" + n + \")\") + \"</button>\").join(\"\") +\n    '<div class=\"muted\" style=\"margin-top:8px\">Savollar testdagi aralashtirish sozlamasiga ko\\'ra tanlanadi.</div></div>';\n  $app.innerHTML = h; bindTabs();\n  $app.querySelectorAll(\"[data-ch]\").forEach((b) => b.onclick = () => { cp.chat = b.dataset.ch; drawChan(); checkJob(); });\n  $app.querySelectorAll(\"[data-iv]\").forEach((b) => b.onclick = () => { cp.interval = +b.dataset.iv; drawChan(job); });\n  $app.querySelectorAll(\"[data-lim]\").forEach((b) => b.onclick = () => { cp.limit = +b.dataset.lim; drawChan(job); });\n  document.getElementById(\"addch\").onclick = async () => {\n    const v = document.getElementById(\"newch\").value.trim();\n    if (!v) return toast(\"Kanal manzilini yozing\");\n    try { const r = await api(\"/cpcheck\", { id: state.quiz.id, channel: v }); haptic(\"success\"); toast(\"✅ \" + r.channel.title + \" qo'shildi\");\n      state.channels = (await api(\"/channels\")).items; cp.chat = r.channel.id; drawChan(); checkJob(); }\n    catch (e) { haptic(\"error\"); toast(\"⚠️ \" + e.message); }\n  };\n  if (cp.chat && !(job && job.busy) && !state.quiz.pending) setMain(\"🚀 Kanalga joylash\", startCp);\n  else setMain(null);\n}\nasync function checkJob() {\n  const cp = state.cp;\n  if (!cp.chat || state.tab !== \"chan\") return;\n  let job = null;\n  try { job = (await api(\"/cpstatus?id=\" + encodeURIComponent(state.quiz.id) + \"&chat=\" + encodeURIComponent(cp.chat))).job; } catch (e) {}\n  if (state.tab !== \"chan\") return;\n  drawChan(job);\n  stopPoll();\n  if (job && !job.busy) { setMain(null); state.poll = setInterval(checkJob, 4000); }\n}\nasync function startCp() {\n  const cp = state.cp, ch = state.channels.find((c) => String(c.id) === String(cp.chat));\n  if (state.dirty) return toast(\"Avval savollardagi o'zgarishlarni saqlang\");\n  if (!(await confirmBox(\"«\" + state.quiz.title + \"» savollarini «\" + (ch ? ch.title : \"\") + \"» kanaliga joylaymi?\"))) return;\n  if (tg) tg.MainButton.showProgress();\n  try { const r = await api(\"/cpstart\", { id: state.quiz.id, chat: cp.chat, interval: cp.interval, limit: cp.limit });\n    haptic(\"success\"); toast(\"🚀 \" + r.total + \" ta savol joylanmoqda\"); checkJob(); }\n  catch (e) { haptic(\"error\"); toast(\"⚠️ \" + e.message); }\n  finally { if (tg) tg.MainButton.hideProgress(); }\n}\n\n// ---------- Javob varaqasi (OMR) ----------\n/*OMR_CODE*/\nconst LET = [\"A\", \"B\", \"C\", \"D\", \"E\"];\nconst aLabel = (a) => (a >= 0 ? LET[a] : a === -2 ? \"2+\" : \"—\");\nasync function renderOmr() {\n  setMain(null);\n  $app.innerHTML = tabsHtml() + '<div class=\"spin\"></div>'; bindTabs();\n  let d;\n  try { d = await api(\"/omrinfo?id=\" + encodeURIComponent(state.quiz.id)); if (!state.brand) state.brand = (await api(\"/brand\")).brand || { name: \"\", logo: null }; }\n  catch (e) { $app.innerHTML = tabsHtml() + '<div class=\"empty\">⚠️ ' + esc(e.message) + \"</div>\"; bindTabs(); return; }\n  if (state.tab !== \"omr\") return;\n  state.omr = d;\n  drawOmr();\n}\nfunction drawOmr() {\n  const d = state.omr;\n  let h = tabsHtml();\n  h += '<div class=\"card\"><h3>1️⃣ Javob varaqasi</h3><div class=\"muted\">' + d.n + \" ta savol · \" + d.k + ' ta variant (A–' + LET[d.k - 1] + \")</div>\" +\n    (d.big ? '<div class=\"muted\" style=\"color:var(--danger)\">Varaqqa birinchi 100 ta savol sig\\'adi.</div>' : \"\") +\n    (d.wide ? '<div class=\"muted\" style=\"color:var(--danger)\">Ba\\'zi savollarda 5 tadan ko\\'p variant bor — varaqda faqat A–E chiqadi.</div>' : \"\") +\n    '<button class=\"btn\" id=\"sheet\" style=\"width:100%;margin-top:10px\">📄 Varaqni botga yuborish (PDF)</button>' +\n    '<div class=\"muted\" style=\"margin-top:6px\">Bot sizga titul (javob varaqasi) va savollar varag\\'ini PDF qilib yuboradi. Chop etib, o\\'quvchilarga tarqating.</div></div>';\n  const br = state.brand || {};\n  h += '<div class=\"card\"><h3>🏫 O\\'quv markazi (titul shapkasi)</h3>' +\n    '<div class=\"row\" style=\"gap:10px\"><div id=\"logoprev\" style=\"width:56px;height:56px;border-radius:10px;background:var(--bg2);display:grid;place-items:center;overflow:hidden;flex:none\">' +\n    (br.logo ? '<img src=\"data:image/' + (br.logo.t === \"png\" ? \"png\" : \"jpeg\") + \";base64,\" + br.logo.d + '\" style=\"max-width:100%;max-height:100%\">' : '<span class=\"muted\">logo</span>') + \"</div>\" +\n    '<input class=\"grow\" id=\"bname\" maxlength=\"80\" placeholder=\"Markaz nomi\" value=\"' + esc(br.name || \"\") + '\"></div>' +\n    '<div class=\"row\" style=\"gap:8px;margin-top:8px\"><label class=\"pick alt grow\" style=\"margin:0\">🖼 Logotip tanlash<input type=\"file\" accept=\"image/*\" id=\"blogo\"></label>' +\n    (br.logo ? '<button class=\"icon del\" id=\"blogodel\" aria-label=\"Logotipni olib tashlash\">✕</button>' : \"\") +\n    '<button class=\"btn\" id=\"bsave\">Saqlash</button></div><div class=\"muted\" style=\"margin-top:6px\">Barcha testlaringiz tituli va savollar varag\\'ida chiqadi.</div></div>';\n  h += '<div class=\"card\"><h3>📥 Savollarni yuklab olish</h3><div class=\"seg\">' +\n    [[\"pdf\", \"📕 PDF\"], [\"doc\", \"📘 Word\"], [\"xls\", \"📗 Excel\"], [\"txt\", \"📄 Matn\"]].map(([f, l]) => '<button class=\"pick alt\" style=\"margin:0\" data-exp=\"' + f + '\">' + l + \"</button>\").join(\"\") +\n    '</div><div class=\"muted\" style=\"margin-top:6px\">Fayl bot chatiga keladi. PDF va Word oxirida javoblar kaliti bor.</div></div>';\n  if (d.ready) {\n    h += '<div class=\"card\"><h3>2️⃣ Skaner qilish</h3>' +\n      '<label class=\"pick\">📷 Varaqni suratga olish<input type=\"file\" accept=\"image/*\" capture=\"environment\" id=\"cam\"></label>' +\n      '<label class=\"pick alt\">🖼 Galereyadan tanlash<input type=\"file\" accept=\"image/*\" id=\"gal\"></label>' +\n      '<ul class=\"tips\"><li>Varaq butunlay kadrga sig\\'sin — 4 ta qora burchak ko\\'rinsin</li><li>Yorug\\' joyda, soya tushirmasdan, tepadan to\\'g\\'ri suratga oling</li><li>Varaqni tekis stolga qo\\'ying</li></ul></div>' +\n      '<div id=\"scanres\"></div>';\n    const sc = d.scans;\n    if (sc.length) {\n      const avg = Math.round(sc.reduce((a, s) => a + s.ok / s.total, 0) / sc.length * 100);\n      h += '<div class=\"card\"><div class=\"row\"><h3 class=\"grow\" style=\"margin:0\">3️⃣ Natijalar: ' + sc.length + ' ta varaq</h3><span class=\"badge\">o\\'rtacha ' + avg + \"%</span></div>\" +\n        sc.map((s) => '<div class=\"li\"><span class=\"grow\">' + (s.student ? \"<b>№\" + esc(s.student) + \"</b> \" : \"\") + esc(s.name || (s.student ? \"\" : \"Ismsiz\")) +\n          '<div class=\"muted\">' + new Date(s.created).toLocaleString(\"uz-UZ\", { day: \"2-digit\", month: \"2-digit\", hour: \"2-digit\", minute: \"2-digit\" }) + \"</div></span>\" +\n          \"<b>\" + s.ok + \"/\" + s.total + '</b><span class=\"badge\">' + Math.round((s.ok / s.total) * 100) + '%</span><button class=\"icon del\" data-dscan=\"' + s.id + '\">✕</button></div>').join(\"\") +\n        '<button class=\"btn\" id=\"xls\" style=\"width:100%;margin-top:10px;background:var(--ok)\">📊 Excel jadvalini botga yuborish</button></div>';\n    }\n  } else h += '<div class=\"card muted\">Skaner qilish uchun avval javob varaqasini oling — shunda savollar va kalit qotiriladi.</div>';\n  $app.innerHTML = h; bindTabs();\n  document.getElementById(\"sheet\").onclick = async (e) => {\n    e.target.disabled = true; e.target.textContent = \"⏳ Tayyorlanmoqda…\";\n    try { await api(\"/omrsheet\", { id: state.quiz.id }); haptic(\"success\"); toast(\"✅ Fayllar botga yuborildi\"); if (!d.ready) return renderOmr(); }\n    catch (err) { haptic(\"error\"); toast(\"⚠️ \" + err.message); }\n    e.target.disabled = false; e.target.textContent = \"📄 Varaqni botga yuborish (PDF)\";\n  };\n  document.getElementById(\"bname\").oninput = (e) => (state.brand.name = e.target.value);\n  document.getElementById(\"blogo\").onchange = async (e) => {\n    const f = e.target.files[0]; if (!f) return;\n    try {\n      const im = await loadImg(f), sc = Math.min(1, 320 / Math.max(im.naturalWidth, im.naturalHeight));\n      const c = document.createElement(\"canvas\"); c.width = Math.round(im.naturalWidth * sc); c.height = Math.round(im.naturalHeight * sc);\n      c.getContext(\"2d\").drawImage(im, 0, 0, c.width, c.height);\n      let url = c.toDataURL(\"image/png\"), t = \"png\";\n      if (url.length > 190000) { const c2 = document.createElement(\"canvas\"); c2.width = c.width; c2.height = c.height; const x = c2.getContext(\"2d\");\n        x.fillStyle = \"#fff\"; x.fillRect(0, 0, c.width, c.height); x.drawImage(c, 0, 0); url = c2.toDataURL(\"image/jpeg\", 0.85); t = \"jpg\"; }\n      state.brand.logo = { t, d: url.split(\",\")[1] };\n      drawOmr(); toast(\"Logotip tanlandi — «Saqlash»ni bosing\");\n    } catch (err) { toast(\"⚠️ \" + err.message); }\n  };\n  const bd = document.getElementById(\"blogodel\"); if (bd) bd.onclick = () => { state.brand.logo = null; drawOmr(); };\n  document.getElementById(\"bsave\").onclick = async () => {\n    try { await api(\"/brand\", { name: state.brand.name || \"\", logo: state.brand.logo }); haptic(\"success\"); toast(\"✅ Saqlandi — endi titulda chiqadi\"); }\n    catch (e) { haptic(\"error\"); toast(\"⚠️ \" + e.message); }\n  };\n  $app.querySelectorAll(\"[data-exp]\").forEach((b) => b.onclick = async () => {\n    const old = b.textContent; b.disabled = true; b.textContent = \"⏳\";\n    try { await api(\"/export\", { id: state.quiz.id, fmt: b.dataset.exp }); haptic(\"success\"); toast(\"✅ Fayl botga yuborildi\"); }\n    catch (e) { toast(\"⚠️ \" + e.message); }\n    b.disabled = false; b.textContent = old;\n  });\n  for (const idn of [\"cam\", \"gal\"]) { const inp = document.getElementById(idn); if (inp) inp.onchange = () => inp.files[0] && scanFile(inp.files[0]); }\n  $app.querySelectorAll(\"[data-dscan]\").forEach((b) => b.onclick = async () => {\n    if (!(await confirmBox(\"Bu natijani o'chiraymi?\"))) return;\n    await api(\"/omrdel\", { id: state.quiz.id, scan: +b.dataset.dscan }).catch(() => {});\n    renderOmr();\n  });\n  const x = document.getElementById(\"xls\");\n  if (x) x.onclick = async () => { try { await api(\"/omrxls\", { id: state.quiz.id }); haptic(\"success\"); toast(\"✅ Excel fayl botga yuborildi\"); } catch (e) { toast(\"⚠️ \" + e.message); } };\n}\nfunction loadImg(file) {\n  return new Promise((res, rej) => {\n    const url = URL.createObjectURL(file), im = new Image();\n    im.onload = () => res(im); im.onerror = () => rej(new Error(\"Rasmni ochib bo'lmadi\"));\n    im.src = url;\n  });\n}\nasync function scanFile(file) {\n  const box = document.getElementById(\"scanres\");\n  box.innerHTML = '<div class=\"card\"><div class=\"spin\" style=\"margin:20px auto\"></div><div class=\"muted\" style=\"text-align:center\">Varaq o\\'qilmoqda…</div></div>';\n  box.scrollIntoView({ behavior: \"smooth\" });\n  let im;\n  try { im = await loadImg(file); } catch (e) { box.innerHTML = '<div class=\"card\">⚠️ ' + e.message + \"</div>\"; return; }\n  await new Promise((r) => setTimeout(r, 30));\n  const sc = Math.min(1, 1400 / Math.max(im.naturalWidth, im.naturalHeight));\n  const w = Math.round(im.naturalWidth * sc), h = Math.round(im.naturalHeight * sc);\n  const cv = document.createElement(\"canvas\"); cv.width = w; cv.height = h;\n  const cx = cv.getContext(\"2d\", { willReadFrequently: true });\n  cx.drawImage(im, 0, 0, w, h);\n  const data = cx.getImageData(0, 0, w, h).data, px = new Uint8Array(w * h);\n  for (let i = 0, j = 0; i < data.length; i += 4, j++) px[j] = (data[i] * 299 + data[i + 1] * 587 + data[i + 2] * 114) / 1000;\n  const L = omrLayout(state.omr.n, state.omr.k);\n  const r = omrScan(px, w, h, L, omrHomography);\n  if (r.error) {\n    haptic(\"error\");\n    box.innerHTML = '<div class=\"card\"><h3>⚠️ Varaq topilmadi</h3><div class=\"muted\">4 ta qora burchak belgisini aniqlab bo\\'lmadi (' + (r.found || 0) + ' tasi topildi). Varaq to\\'liq kadrda, yorug\\' va tekis bo\\'lsin, so\\'ng qaytadan suratga oling.</div></div>';\n    return;\n  }\n  state.scan = { answers: r.answers.slice(), id: r.id, cv, map: r.map, L };\n  haptic(\"success\");\n  drawScan();\n}\nfunction drawScan() {\n  const s = state.scan, key = state.omr.key, L = s.L;\n  const ok = s.answers.filter((a, i) => a === key[i]).length;\n  // Natijani suratga chizamiz\n  const out = document.createElement(\"canvas\"); out.width = s.cv.width; out.height = s.cv.height; out.className = \"prev\";\n  const c = out.getContext(\"2d\"); c.drawImage(s.cv, 0, 0);\n  const scale = Math.hypot(...s.map(L.r, 0).map((v, i) => v - s.map(0, 0)[i]));\n  const ring = (pt, color, wd) => { const [u, v] = s.map(...pt); c.beginPath(); c.arc(u, v, scale * 1.25, 0, 7); c.strokeStyle = color; c.lineWidth = wd; c.stroke(); };\n  L.q.forEach((opts, i) => {\n    const a = s.answers[i], k = key[i];\n    if (a >= 0) ring(opts[a], a === k ? \"#2fa24f\" : \"#e5484d\", Math.max(2, scale * 0.45));\n    if (a !== k && opts[k]) ring(opts[k], \"#2a7de1\", Math.max(1.5, scale * 0.3));\n  });\n  const pct = Math.round((ok / L.n) * 100);\n  const box = document.getElementById(\"scanres\");\n  box.innerHTML = '<div class=\"card\"><div class=\"row\"><h3 class=\"grow\" style=\"margin:0\">✅ Varaq o\\'qildi</h3><b style=\"font-size:20px\">' + ok + \"/\" + L.n + '</b><span class=\"badge\">' + pct + \"%</span></div>\" +\n    '<div class=\"muted\" style=\"margin:4px 0 10px\">🟢 to\\'g\\'ri · 🔴 xato · 🔵 to\\'g\\'ri javob. Noto\\'g\\'ri o\\'qilgan javobni pastdagi katakni bosib tuzating.</div>' +\n    '<div id=\"prevbox\"></div>' +\n    '<label class=\"f\">O\\'quvchi ismi (ixtiyoriy)</label><input id=\"sname\" maxlength=\"60\" placeholder=\"Ism-familiya\">' +\n    '<div class=\"agrid\">' + s.answers.map((a, i) => '<button data-cyc=\"' + i + '\" class=\"' + (a === key[i] ? \"ok\" : a === -1 ? \"no blank\" : \"no\") + '\"><span class=\"muted\">' + (i + 1) + \"</span><b>\" + aLabel(a) + \"</b></button>\").join(\"\") + \"</div>\" +\n    (tg ? \"\" : '<button class=\"btn\" id=\"savescan\" style=\"width:100%;margin-top:10px\">✅ Saqlash</button>') + \"</div>\";\n  document.getElementById(\"prevbox\").appendChild(out);\n  const name = state.scan.name; if (name) document.getElementById(\"sname\").value = name;\n  document.getElementById(\"sname\").oninput = (e) => (state.scan.name = e.target.value);\n  $app.querySelectorAll(\"[data-cyc]\").forEach((b) => b.onclick = () => {\n    const i = +b.dataset.cyc, a = s.answers[i];\n    s.answers[i] = a < 0 ? 0 : a + 1 >= L.k ? -1 : a + 1;\n    drawScan(); document.querySelector('[data-cyc=\"' + i + '\"]').scrollIntoView({ block: \"nearest\" });\n  });\n  setMain(\"✅ Natijani saqlash\", saveScan);\n  const sv = document.getElementById(\"savescan\"); if (sv) sv.onclick = saveScan;\n}\nasync function saveScan() {\n  const s = state.scan;\n  if (tg) tg.MainButton.showProgress();\n  try {\n    const r = await api(\"/omr\", { id: state.quiz.id, answers: s.answers, student: s.id, name: s.name || \"\" });\n    haptic(\"success\"); toast(\"✅ Saqlandi: \" + r.score + \"/\" + r.total + \" — keyingi varaqni suratga oling\");\n    state.scan = null; setMain(null); await renderOmr();\n  } catch (e) { haptic(\"error\"); toast(\"⚠️ \" + e.message); }\n  finally { if (tg) tg.MainButton.hideProgress(); }\n}\n\n// ---------- Bosh sahifa: test yechish / mening testlarim ----------\nconst homeTabs = () => '<div class=\"tabs\">' + [[\"play\", \"🎯 Yechish\"], [\"mine\", \"✏️ Testlarim\"], [\"new\", \"➕ Yangi\"], [\"more\", \"☰ Ko\\'proq\"]]\n  .map(([k, v]) => '<button data-home=\"' + k + '\" class=\"' + (state.home === k ? \"on\" : \"\") + '\">' + v + \"</button>\").join(\"\") + \"</div>\";\nfunction bindHome() {\n  $app.querySelectorAll(\"[data-home]\").forEach((b) => b.onclick = () => { stopPoll(); stopTimer(); setMain(null);\n    ({ play: loadCatalog, mine: loadList, new: loadNew, more: loadMore })[b.dataset.home](); });\n}\nconst qItem = (q) => '<div class=\"item\" data-play=\"' + esc(q.id) + '\"><div class=\"grow\"><div class=\"t\">' + esc(q.title) +\n  '</div><div class=\"muted\">🖊 ' + q.count + ' ta savol</div></div><span class=\"muted\">▶️</span></div>';\nasync function loadCatalog() {\n  state.view = \"home\"; state.home = \"play\"; state.quiz = null; stopPoll(); stopTimer();\n  setBack(null); setMain(null);\n  $app.innerHTML = homeTabs() + '<div class=\"spin\"></div>'; bindHome();\n  let d;\n  try { d = await api(\"/catalog\"); } catch (e) { $app.innerHTML = homeTabs() + '<div class=\"empty\">⚠️ ' + esc(e.message) + \"</div>\"; bindHome(); return; }\n  if (state.home !== \"play\") return;\n  let h = homeTabs();\n  if (d.pub.length) h += '<div class=\"sec\">👨‍🏫 Muallif testlari · ' + esc(d.author) + \"</div>\" + d.pub.map(qItem).join(\"\");\n  if (d.mine.length) h += '<div class=\"sec\">📝 O\\'zim tuzgan testlar</div>' + d.mine.map(qItem).join(\"\");\n  if (!d.pub.length && !d.mine.length) h += '<div class=\"empty\">Hozircha testlar yo\\'q.<br>Do\\'stingiz yuborgan test havolasini oching yoki botga fayl yuborib test tuzing.</div>';\n  $app.innerHTML = h; bindHome();\n  $app.querySelectorAll(\"[data-play]\").forEach((el) => el.onclick = () => openPlay(el.dataset.play));\n}\n\n// ---------- Test yechish ----------\nfunction stopTimer() { clearInterval(state.tick); state.tick = null; }\nasync function openPlay(id) {\n  stopTimer(); setMain(null); setBack(() => loadCatalog());\n  state.view = \"intro\";\n  $app.innerHTML = '<div class=\"spin\"></div>';\n  let d;\n  try { d = await api(\"/info?id=\" + encodeURIComponent(id)); } catch (e) { toast(\"⚠️ \" + e.message); return loadCatalog(); }\n  state.info = d;\n  const medals = [\"🥇\", \"🥈\", \"🥉\"];\n  $app.innerHTML = '<div class=\"card hero\"><div class=\"big\">🎲</div><h2>' + esc(d.title) + \"</h2>\" +\n    (d.description ? '<div class=\"muted\">' + esc(d.description) + \"</div>\" : \"\") +\n    '<div class=\"meta\"><span>🖊 ' + d.count + ' ta savol</span><span>⏱ ' + tLabel(d.timer) + '</span><span>👥 ' + d.takers + \" kishi</span></div></div>\" +\n    (d.top.length ? '<div class=\"card\"><h3>🏆 Eng yaxshi natijalar</h3>' + d.top.map((r, i) =>\n      '<div class=\"li\"><span style=\"width:26px\">' + medals[i] + '</span><span class=\"grow\">' + esc(r.name) + \"</span><b>\" + r.ok + \"/\" + r.total + \"</b></div>\").join(\"\") + \"</div>\" : \"\") +\n    '<div class=\"card muted\">Har bir savolga ' + tLabel(d.timer) + ' beriladi. Natijangiz reytingga yoziladi, xato qilgan so\\'zlaringiz takrorlash ro\\'yxatiga tushadi.</div>' +\n    (d.owner ? '<button class=\"ghost\" id=\"toedit\" style=\"width:100%\">✏️ Testni tahrirlash</button>' : \"\") +\n    (tg ? \"\" : '<button class=\"btn\" id=\"go\" style=\"width:100%\">▶️ Boshlash</button>');\n  setMain(\"▶️ Testni boshlash\", () => startPlay(false));\n  const te = document.getElementById(\"toedit\"); if (te) te.onclick = () => openQuiz(d.id);\n  const go = document.getElementById(\"go\"); if (go) go.onclick = () => startPlay(false);\n}\nasync function startPlay(retry) {\n  setMain(null);\n  $app.innerHTML = '<div class=\"spin\"></div>';\n  let r;\n  try { r = await api(\"/play\", state.info.review ? { review: state.info.review } : { id: state.info.id, retry }); }\n  catch (e) {\n    if (e.message === \"join\") return showJoin((e.data && e.data.channels) || [], retry);\n    toast(\"⚠️ \" + e.message); return state.info.review ? loadMore() : openPlay(state.info.id);\n  }\n  state.game = { ...r, i: 0, ok: 0, done: false, retry };\n  setBack(async () => { if (await confirmBox(\"Testni shu yerda yakunlaymi? Javob berilgan savollar hisoblanadi.\")) finishPlay(); });\n  renderQ();\n}\nfunction showJoin(chans, retry) {\n  setBack(() => openPlay(state.info.id));\n  $app.innerHTML = '<div class=\"card hero\"><div class=\"big\">📢</div><h2>Kanallarga a\\'zo bo\\'ling</h2><div class=\"muted\">Testni yechish uchun avval quyidagi kanallarimizga a\\'zo bo\\'ling.</div></div>' +\n    chans.map((c) => '<button class=\"ans\" data-link=\"' + esc(c.link) + '\">📢 ' + esc(c.name) + \"</button>\").join(\"\");\n  $app.querySelectorAll(\"[data-link]\").forEach((b) => b.onclick = () => (tg.openTelegramLink ? tg.openTelegramLink(b.dataset.link) : window.open(b.dataset.link)));\n  setMain(\"✅ A'zo bo'ldim — tekshirish\", () => startPlay(retry));\n}\nfunction renderQ() {\n  const g = state.game, q = g.questions[g.i];\n  stopTimer(); setMain(null);\n  g.answered = false;\n  const img = q.img ? '<img src=\"/api/img?f=' + encodeURIComponent(q.img) + '\" alt=\"\">' : \"\";\n  $app.innerHTML = '<div class=\"playtop\"><span class=\"grow\">' + esc(g.title) + \"</span><span>\" + (g.i + 1) + \" / \" + g.total + \"</span>\" +\n    '<span class=\"badge\" id=\"tleft\">' + g.timer + \"s</span></div>\" +\n    '<div class=\"tbar\" id=\"tbar\"><div style=\"width:100%\"></div></div>' +\n    '<div class=\"qbox\">' + img + esc(q.q) + \"</div>\" +\n    q.opts.map((o, k) => '<button class=\"ans\" data-k=\"' + k + '\">' + esc(o) + \"</button>\").join(\"\") + '<div id=\"after\"></div>';\n  $app.querySelectorAll(\"[data-k]\").forEach((b) => b.onclick = () => answer(+b.dataset.k));\n  const end = Date.now() + g.timer * 1000;\n  const bar = document.querySelector(\"#tbar > div\"), left = document.getElementById(\"tleft\"), tb = document.getElementById(\"tbar\");\n  state.tick = setInterval(() => {\n    const ms = end - Date.now();\n    if (ms <= 0) { stopTimer(); answer(-1); return; }\n    bar.style.width = (ms / (g.timer * 1000)) * 100 + \"%\";\n    left.textContent = Math.ceil(ms / 1000) + \"s\";\n    tb.classList.toggle(\"low\", ms < 5000);\n  }, 200);\n  window.scrollTo(0, 0);\n}\nasync function answer(k) {\n  const g = state.game;\n  if (g.answered) return;\n  g.answered = true; stopTimer();\n  const btns = $app.querySelectorAll(\"[data-k]\");\n  btns.forEach((b) => (b.disabled = true));\n  let r;\n  try { r = await api(\"/answer\", { i: g.i, c: k }); }\n  catch (e) { toast(\"⚠️ \" + e.message); g.answered = false; btns.forEach((b) => (b.disabled = false)); return; }\n  btns[r.right] && btns[r.right].classList.add(\"right\");\n  if (!r.ok && k >= 0) btns[k].classList.add(\"wrong\");\n  if (r.ok) { g.ok++; haptic(\"success\"); } else haptic(\"error\");\n  const after = document.getElementById(\"after\");\n  if (k < 0) after.innerHTML = '<div class=\"expl\">⌛️ Vaqt tugadi</div>';\n  if (!r.ok && r.exp) after.innerHTML += '<div class=\"expl\">💬 ' + esc(r.exp) + \"</div>\";\n  const last = g.i + 1 >= g.total;\n  const next = () => { if (last) finishPlay(); else { g.i++; renderQ(); } };\n  if (r.ok) { setTimeout(() => { if (state.game === g && g.answered) next(); }, 800); }\n  else setMain(last ? \"🏁 Natijani ko'rish\" : \"Keyingi savol ➜\", next);\n  if (!tg && !r.ok) { const b = document.createElement(\"button\"); b.className = \"btn\"; b.style.width = \"100%\"; b.textContent = last ? \"🏁 Natija\" : \"Keyingi ➜\"; b.onclick = next; after.appendChild(b); }\n}\nasync function finishPlay() {\n  const g = state.game;\n  const rev = !!state.info.review;\n  stopTimer(); setMain(null); setBack(() => (rev ? loadMore() : loadCatalog()));\n  $app.innerHTML = '<div class=\"spin\"></div>';\n  let r;\n  try { r = await api(\"/finish\", {}); } catch (e) { toast(\"⚠️ \" + e.message); return rev ? loadMore() : openPlay(state.info.id); }\n  state.game = null;\n  const pct = r.asked ? Math.round((r.ok / r.asked) * 100) : 0;\n  const emoji = pct >= 90 ? \"🏆\" : pct >= 70 ? \"🎉\" : pct >= 50 ? \"👍\" : \"💪\";\n  const medals = [\"🥇\", \"🥈\", \"🥉\", \"4.\", \"5.\"];\n  let h = '<div class=\"card hero\"><div class=\"big\">' + emoji + '</div><div class=\"score\">' + pct + '%</div><div class=\"muted\" style=\"margin-top:6px\">' + esc(r.title) + \"</div>\" +\n    (r.place ? '<div style=\"margin-top:10px\">🏆 ' + r.players + \" ishtirokchi ichida <b>\" + r.place + \"-o'rin</b>\" + (r.improved ? \"<br>📈 Yangi rekord!\" : \"\") + \"</div>\" : \"\") + \"</div>\" +\n    '<div class=\"rgrid\"><div><b style=\"color:var(--ok)\">' + r.ok + '</b>To\\'g\\'ri</div><div><b style=\"color:var(--danger)\">' + r.bad + '</b>Xato</div><div><b>' + r.missed + \"</b>O'tkazilgan</div></div>\" +\n    '<div class=\"card muted\" style=\"text-align:center\">⏱ ' + fmtT(r.secs) + \" · \" + r.asked + \" / \" + r.total + \" savolga javob berildi\" +\n    (r.reviewAdded ? \"<br>🧠 \" + r.reviewAdded + \" ta so'z takrorlash ro'yxatiga qo'shildi\" : \"\") +\n    (r.review ? \"<br>🧠 \" + (r.review.mastered ? \"✅ O'zlashtirildi: \" + r.review.mastered + \" ta · \" : \"\") + (r.review.advanced ? \"📈 Keyingi bosqich: \" + r.review.advanced + \" ta · \" : \"\") +\n      \"Ro'yxatda qoldi: \" + r.review.left + \" ta\" : \"\") + \"</div>\";\n  if (r.wrong.length) h += '<div class=\"card\"><h3>📝 Takrorlash kerak</h3>' + r.wrong.map((w) =>\n    '<div class=\"li\"><span class=\"grow\">' + esc(w.q) + '<div class=\"q-ans\">✓ ' + esc(w.ans) + \"</div></span></div>\").join(\"\") + \"</div>\";\n  if (r.top && r.top.length) h += '<div class=\"card\"><h3>🏆 Eng yaxshi 5 natija</h3>' + r.top.map((t, i) =>\n    '<div class=\"li\"><span style=\"width:26px\">' + medals[i] + '</span><span class=\"grow\">' + esc(t.name) + \"</span><b>\" + t.ok + \"/\" + t.total + '</b><span class=\"muted\">' + fmtT(t.secs) + \"</span></div>\").join(\"\") + \"</div>\";\n  h += '<div class=\"row\" style=\"gap:8px\">' + (r.wrong.length && !rev ? '<button class=\"btn grow\" id=\"retry\">🎯 Xatolarni ishlash</button>' : \"\") +\n    '<button class=\"btn grow\" id=\"again\" style=\"background:var(--card);color:var(--text)\">' + (rev ? \"🧠 Takrorlash bo\\'limi\" : \"🔁 Qayta yechish\") + \"</button></div>\" +\n    (rev ? \"\" : '<button class=\"ghost\" id=\"share\" style=\"width:100%;margin-top:8px\">🔗 Testni do\\'stlarga ulashish</button>');\n  $app.innerHTML = h; window.scrollTo(0, 0);\n  const rt = document.getElementById(\"retry\"); if (rt) rt.onclick = () => startPlay(true);\n  document.getElementById(\"again\").onclick = () => (rev ? loadMore() : startPlay(false));\n  const sh = document.getElementById(\"share\"); if (sh) sh.onclick = () => { try { tg.switchInlineQuery(state.info.id, [\"users\", \"groups\", \"channels\"]); } catch (e) { toast(\"Ulashib bo'lmadi\"); } };\n}\n\n// ---------- ➕ Yangi test ----------\nconst TIMERS = [10, 15, 30, 45, 60, 120, 180, 240, 300, 600];\nconst DIRS = { fwd: \"So'z → tarjima\", rev: \"Tarjima → so'z\", mix: \"Aralash\" };\nasync function loadNew(force) {\n  state.view = \"home\"; state.home = \"new\"; state.quiz = null;\n  setBack(null); setMain(null);\n  $app.innerHTML = homeTabs() + '<div class=\"spin\"></div>'; bindHome();\n  let info = { none: true };\n  if (!force) try { info = await api(\"/srcinfo\"); } catch (e) {}\n  if (state.home !== \"new\") return;\n  if (info.kind) return renderCreateForm(info);\n  $app.innerHTML = homeTabs() +\n    '<div class=\"card hero\"><div class=\"big\">📄</div><h2>Fayldan test tuzish</h2><div class=\"muted\">PDF, Word, Excel, TXT yoki CSV faylni yuklang — bot savollarni o\\'zi tuzadi: lug\\'atdan ham, tayyor test savollaridan ham.</div></div>' +\n    '<label class=\"pick\">📎 Fayl tanlash<input type=\"file\" id=\"nfile\" accept=\".pdf,.doc,.docx,.xls,.xlsx,.txt,.csv,application/pdf,text/plain\"></label>' +\n    '<label class=\"pick alt\" id=\"manual\">✍️ Savollarni qo\\'lda yozish</label>' +\n    '<div class=\"card\" style=\"margin-top:12px\"><h3>📘 Fayl qanday bo\\'lishi kerak?</h3><div class=\"muted\">Lug\\'at: har qatorda <b>so\\'z - tarjima</b>. Test: savol, A) B) C) D) variantlar va <b>Javob: B</b>.</div>' +\n    '<div class=\"seg\" style=\"margin-top:10px\"><button class=\"pick alt\" style=\"margin:0\" data-g=\"fmt\">📘 Yo\\'riqnoma</button><button class=\"pick alt\" style=\"margin:0\" data-g=\"all\">🗂 Namunalar</button></div></div>';\n  bindHome();\n  $app.querySelectorAll(\"[data-g]\").forEach((b) => b.onclick = () => sendGuide(b.dataset.g));\n  document.getElementById(\"manual\").onclick = () => {\n    state.quiz = { manual: true, title: \"\", description: \"\", timer: 30, shuffle: \"all\", timers: TIMERS, questions: [{ q: \"\", opts: [\"\", \"\", \"\", \"\"], correct: 0 }] };\n    state.view = \"edit\"; state.open = 0; state.filter = \"\"; state.dirty = false; state.tab = \"edit\";\n    setBack(goBack); renderEdit();\n  };\n  document.getElementById(\"nfile\").onchange = async (e) => {\n    const f = e.target.files[0]; if (!f) return;\n    if (f.size > 20 * 1024 * 1024) return toast(\"⚠️ Fayl 20 MB dan katta\");\n    $app.innerHTML = homeTabs() + '<div class=\"card hero\"><div class=\"spin\" style=\"margin:10px auto\"></div><div class=\"muted\">«' + esc(f.name) + '» o\\'qilmoqda…</div></div>'; bindHome();\n    try {\n      const r = await fetch(\"/api/parse\", { method: \"POST\", headers: { \"X-Init-Data\": tg.initData, \"X-File-Name\": encodeURIComponent(f.name) }, body: await f.arrayBuffer() });\n      const j = await r.json().catch(() => ({ error: \"Server javob bermadi\" }));\n      if (!r.ok || j.error) throw new Error(j.error || \"Xatolik\");\n      haptic(\"success\"); state.cf = null; renderCreateForm(j);\n    } catch (err) { haptic(\"error\"); toast(\"⚠️ \" + err.message); loadNew(true); }\n  };\n}\nasync function sendGuide(what) {\n  try { await api(\"/guide\", { what }); haptic(\"success\"); toast(\"✅ Botga yuborildi — chatni oching\"); } catch (e) { toast(\"⚠️ \" + e.message); }\n}\nfunction renderCreateForm(info) {\n  const cf = state.cf = state.cf && state.cf.file === info.file ? state.cf : { file: info.file, lessons: [], sections: [], count: 0, split: 0, order: \"seq\",\n    direction: \"fwd\", title: info.title, description: \"\", timer: 30, shuffle: \"all\", n: info.kind === \"mcq\" ? info.count : info.total, secs: info.sections || [] };\n  const mcq = info.kind === \"mcq\";\n  const chip = (on, attr, label) => '<button class=\"chip' + (on ? \" on\" : \"\") + '\" ' + attr + \">\" + label + \"</button>\";\n  let h = homeTabs() + '<div class=\"card\"><div class=\"row\"><div class=\"grow\"><b>📄 ' + esc(info.file) + '</b><div class=\"muted\">' +\n    (mcq ? \"✅ \" + info.count + \" ta test savoli\" + (info.img ? \" · 🖼 \" + info.img : \"\") + (info.expl ? \" · 💬 \" + info.expl : \"\") : \"📖 \" + info.total + \" ta so'z\" + (info.lessons.length ? \" · \" + info.lessons.length + \" dars\" : \"\")) +\n    '</div></div><button class=\"ghost\" id=\"other\">Boshqa fayl</button></div>' +\n    (info.missing ? '<div class=\"muted\" style=\"color:var(--danger)\">⚠️ ' + info.missing + \" ta savolda to'g'ri javob yo'q — qo'shilmadi.</div>\" : \"\") + \"</div>\";\n  if (!mcq && info.lessons.length) {\n    const levels = [...new Set(info.lessons.map((l) => l.level))];\n    h += '<div class=\"card\"><h3>📚 Darslar</h3><div class=\"muted\">Tanlanmasa — butun kitob.</div>' + levels.map((lv) => {\n      const ls = info.lessons.filter((l) => l.level === lv), all = ls.every((l) => cf.lessons.includes(l.i));\n      return '<div style=\"margin-top:8px\"><b>' + esc(lv) + \"</b> \" + chip(all, 'data-lv=\"' + esc(lv) + '\"', \"Hammasi\") + \"<br>\" +\n        ls.map((l) => chip(cf.lessons.includes(l.i), 'data-ls=\"' + l.i + '\"', esc(String(l.name).replace(/^\\S+\\s/, \"\")) + \" · \" + l.count)).join(\"\") + \"</div>\";\n    }).join(\"\") + \"</div>\";\n  }\n  if (!mcq && cf.secs.length > 1) h += '<div class=\"card\"><h3>🗂 Bo\\'limlar</h3><div class=\"muted\">Tanlanmasa — hammasi.</div>' +\n    cf.secs.map((x) => chip(cf.sections.includes(x.name), 'data-sec=\"' + esc(x.name) + '\"', esc(x.name) + \" · \" + x.count)).join(\"\") + \"</div>\";\n  const n = cf.n, cnt = cf.count || n;\n  h += '<div class=\"card\"><h3>🖊 Savollar soni — ' + n + \" tadan</h3>\" +\n    [10, 20, 30, 50, 100].filter((v) => v < n).map((v) => chip(cf.count === v && !cf.split, 'data-cnt=\"' + v + '\"', v)).join(\"\") + chip(!cf.split && (!cf.count || cf.count >= n), 'data-cnt=\"0\"', \"Hammasi (\" + n + \")\") +\n    '<div class=\"row\" style=\"margin-top:8px\"><span class=\"muted grow\">Yoki boshqa son:</span><input id=\"cnt\" inputmode=\"numeric\" style=\"width:90px\" value=\"' + (cf.split ? \"\" : cnt) + '\"></div>' +\n    (n >= 8 ? '<label class=\"row\" style=\"margin-top:12px;gap:8px\"><input type=\"checkbox\" id=\"splt\" style=\"width:auto\"' + (cf.split ? \" checked\" : \"\") + '><span>✂️ Qismlarga bo\\'lib, bir nechta test tuzish</span></label>' +\n      (cf.split ? '<div class=\"row\" style=\"margin-top:8px\"><span class=\"muted grow\">Har qismda nechta savol:</span><input id=\"spsz\" inputmode=\"numeric\" style=\"width:90px\" value=\"' + cf.split + '\"></div>' +\n        '<div class=\"muted\" style=\"margin-top:4px\">→ ' + Math.ceil(n / cf.split) + \" ta test</div>\" +\n        chip(cf.order === \"seq\", 'data-ord=\"seq\"', \"📖 Fayldagi tartibda\") + chip(cf.order === \"rnd\", 'data-ord=\"rnd\"', \"🔀 Aralashtirib\") : \"\") : \"\") + \"</div>\";\n  if (!mcq) h += '<div class=\"card\"><h3>🔀 Savol yo\\'nalishi</h3>' + Object.entries(DIRS).map(([k, v]) => chip(cf.direction === k, 'data-dir=\"' + k + '\"', v)).join(\"\") + \"</div>\";\n  h += '<div class=\"card\"><label class=\"f\" style=\"margin-top:0\">Test nomi</label><input id=\"ctitle\" maxlength=\"100\" value=\"' + esc(cf.title) + '\">' +\n    '<label class=\"f\">Tavsif (ixtiyoriy)</label><textarea id=\"cdesc\" rows=\"2\" maxlength=\"300\">' + esc(cf.description) + \"</textarea>\" +\n    '<div class=\"seg\"><div><label class=\"f\">⏱ Har savolga</label><select id=\"ctimer\">' + TIMERS.map((t) => '<option value=\"' + t + '\"' + (t === cf.timer ? \" selected\" : \"\") + \">\" + tLabel(t) + \"</option>\").join(\"\") + \"</select></div>\" +\n    '<div><label class=\"f\">🔀 Aralashtirish</label><select id=\"cshuf\">' + Object.entries(SHUF).map(([k, v]) => '<option value=\"' + k + '\"' + (k === cf.shuffle ? \" selected\" : \"\") + \">\" + v + \"</option>\").join(\"\") + \"</select></div></div></div>\" +\n    (tg ? \"\" : '<button class=\"btn\" id=\"cgo\" style=\"width:100%\">✅ Testni yaratish</button>');\n  $app.innerHTML = h; bindHome();\n  const redraw = () => renderCreateForm(info);\n  const repick = async () => {\n    try { const r = await api(\"/srcpick\", { lessons: cf.lessons, sections: cf.sections }); cf.n = r.n; cf.secs = r.sections; cf.sections = cf.sections.filter((x) => r.sections.some((y) => y.name === x)); }\n    catch (e) { toast(\"⚠️ \" + e.message); }\n    if (cf.count > cf.n) cf.count = 0; if (cf.split >= cf.n) cf.split = 0; redraw();\n  };\n  document.getElementById(\"other\").onclick = () => loadNew(true);\n  $app.querySelectorAll(\"[data-ls]\").forEach((b) => b.onclick = () => { const i = +b.dataset.ls; cf.lessons = cf.lessons.includes(i) ? cf.lessons.filter((x) => x !== i) : [...cf.lessons, i]; repick(); });\n  $app.querySelectorAll(\"[data-lv]\").forEach((b) => b.onclick = () => { const ids = info.lessons.filter((l) => l.level === b.dataset.lv).map((l) => l.i);\n    const all = ids.every((i) => cf.lessons.includes(i)); cf.lessons = all ? cf.lessons.filter((i) => !ids.includes(i)) : [...new Set([...cf.lessons, ...ids])]; repick(); });\n  $app.querySelectorAll(\"[data-sec]\").forEach((b) => b.onclick = () => { const v = b.dataset.sec; cf.sections = cf.sections.includes(v) ? cf.sections.filter((x) => x !== v) : [...cf.sections, v]; repick(); });\n  $app.querySelectorAll(\"[data-cnt]\").forEach((b) => b.onclick = () => { cf.count = +b.dataset.cnt; cf.split = 0; redraw(); });\n  $app.querySelectorAll(\"[data-dir]\").forEach((b) => b.onclick = () => { cf.direction = b.dataset.dir; redraw(); });\n  $app.querySelectorAll(\"[data-ord]\").forEach((b) => b.onclick = () => { cf.order = b.dataset.ord; redraw(); });\n  const ci = document.getElementById(\"cnt\"); ci.onchange = () => { const v = parseInt(ci.value, 10); cf.count = v > 0 ? Math.min(v, cf.n) : 0; cf.split = 0; redraw(); };\n  const sp = document.getElementById(\"splt\"); if (sp) sp.onchange = () => { cf.split = sp.checked ? Math.min(20, Math.max(2, Math.floor(cf.n / 2))) : 0; redraw(); };\n  const ss = document.getElementById(\"spsz\"); if (ss) ss.onchange = () => { const v = parseInt(ss.value, 10); cf.split = v > 0 && v < cf.n ? v : cf.split; redraw(); };\n  document.getElementById(\"ctitle\").oninput = (e) => (cf.title = e.target.value);\n  document.getElementById(\"cdesc\").oninput = (e) => (cf.description = e.target.value);\n  document.getElementById(\"ctimer\").onchange = (e) => (cf.timer = +e.target.value);\n  document.getElementById(\"cshuf\").onchange = (e) => (cf.shuffle = e.target.value);\n  const go = async () => {\n    if (!cf.title.trim()) return toast(\"Test nomini yozing\");\n    if (tg) tg.MainButton.showProgress();\n    try {\n      const r = await api(\"/create\", { lessons: cf.lessons, sections: cf.sections, count: cf.count || cf.n, split: cf.split, order: cf.order, direction: cf.direction,\n        title: cf.title, description: cf.description, timer: cf.timer, shuffle: cf.shuffle });\n      haptic(\"success\"); state.cf = null; renderMade(r);\n    } catch (e) { haptic(\"error\"); toast(\"⚠️ \" + e.message); }\n    finally { if (tg) tg.MainButton.hideProgress(); }\n  };\n  setMain(cf.split ? \"✅ \" + Math.ceil(cf.n / cf.split) + \" ta test yaratish\" : \"✅ Testni yaratish\", go);\n  const cg = document.getElementById(\"cgo\"); if (cg) cg.onclick = go;\n}\nfunction renderMade(r) {\n  setMain(null); setBack(null);\n  state.view = \"home\"; state.home = \"new\"; state.quiz = null;\n  const pend = r.made.filter((m) => m.pending).length;\n  $app.innerHTML = homeTabs() + '<div class=\"card hero\"><div class=\"big\">🎉</div><h2>' + (r.made.length > 1 ? r.made.length + \" ta test yaratildi!\" : \"Test yaratildi!\") + \"</h2>\" +\n    (pend ? '<div class=\"muted\">⏳ ' + pend + \" ta test muallif tekshiruviga yuborildi.</div>\" : \"\") +\n    (r.author ? '<div class=\"muted\">🔒 Hozircha faqat sizga ko\\'rinadi — botda «🌐 Hammaga ko\\'rsatish» ni bosing.</div>' : \"\") + \"</div>\" +\n    r.made.map((m) => '<div class=\"item\" data-ed=\"' + esc(m.id) + '\"><div class=\"grow\"><div class=\"t\">' + (m.pending ? \"⏳ \" : \"🎲 \") + esc(m.title) +\n      '</div><div class=\"muted\">🖊 ' + m.n + \" ta savol</div></div>\" + (m.pending ? \"\" : '<button class=\"icon\" data-pl=\"' + esc(m.id) + '\">▶️</button>') + \"</div>\").join(\"\") +\n    '<button class=\"pick alt\" id=\"again\">➕ Yana test tuzish</button>';\n  bindHome();\n  $app.querySelectorAll(\"[data-ed]\").forEach((el) => el.onclick = (e) => { if (e.target.closest(\"[data-pl]\")) return; openQuiz(el.dataset.ed); });\n  $app.querySelectorAll(\"[data-pl]\").forEach((b) => b.onclick = () => openPlay(b.dataset.pl));\n  document.getElementById(\"again\").onclick = () => loadNew();\n}\n\n// ---------- ☰ Ko'proq: takrorlash, yo'riqnoma, muallif, sozlamalar, qo'llab-quvvatlash ----------\nasync function loadMore() {\n  state.view = \"home\"; state.home = \"more\"; state.quiz = null;\n  setBack(null); setMain(null);\n  $app.innerHTML = homeTabs() + '<div class=\"spin\"></div>'; bindHome();\n  let d;\n  try { d = await api(\"/more\"); } catch (e) { $app.innerHTML = homeTabs() + '<div class=\"empty\">⚠️ ' + esc(e.message) + \"</div>\"; bindHome(); return; }\n  if (state.home !== \"more\") return;\n  state.more = d;\n  const rv = d.review, when = rv.next ? new Date(rv.next).toLocaleString(\"uz-UZ\", { day: \"2-digit\", month: \"2-digit\", hour: \"2-digit\", minute: \"2-digit\" }) : \"\";\n  let h = homeTabs();\n  h += '<div class=\"card\"><h3>🧠 Takrorlash</h3>' + (rv.total\n    ? '<div class=\"stats\" style=\"margin:0 0 8px\"><div class=\"stat\" style=\"background:var(--bg2)\"><span class=\"muted\">Ro\\'yxatda</span><b>' + rv.total + '</b></div><div class=\"stat\" style=\"background:var(--bg2)\"><span class=\"muted\">Bugun</span><b>' + rv.due + \"</b></div></div>\" +\n      (rv.due ? '<button class=\"btn\" id=\"rvdue\" style=\"width:100%\">▶️ Takrorlashni boshlash (' + Math.min(rv.due, 50) + \")</button>\"\n        : '<div class=\"muted\">✅ Bugun uchun takrorlash yo\\'q.' + (when ? \" Keyingisi: \" + when : \"\") + '</div><button class=\"pick alt\" id=\"rvall\">🔁 Hozir mashq qilish (' + Math.min(rv.total, 50) + \")</button>\")\n    : '<div class=\"muted\">Ro\\'yxatingiz bo\\'sh. Testlarda xato qilgan so\\'zlaringiz shu yerga tushadi va 1, 3, 7 kundan keyin qayta so\\'raladi. 3 marta to\\'g\\'ri topilgan so\\'z o\\'zlashtirilgan hisoblanadi.</div>') + \"</div>\";\n  h += '<div class=\"card\"><h3>📖 Yo\\'riqnoma va namunalar</h3><div class=\"muted\">Fayl bot chatiga yuboriladi.</div><div class=\"seg\" style=\"margin-top:8px\">' +\n    (d.guide.bot ? '<button class=\"pick alt\" style=\"margin:0\" data-g=\"bot\">📖 Bot yo\\'riqnomasi</button>' : \"\") +\n    (d.guide.fmt ? '<button class=\"pick alt\" style=\"margin:0\" data-g=\"fmt\">📘 Test fayli formati</button>' : \"\") + \"</div>\" +\n    (d.guide.samples.length ? '<div style=\"margin-top:8px\">' + d.guide.samples.map((t, i) => '<button class=\"chip\" data-g=\"' + i + '\">📄 ' + esc(t) + \"</button>\").join(\"\") +\n      (d.guide.samples.length > 1 ? '<button class=\"chip\" data-g=\"all\">📦 Hammasi</button>' : \"\") + \"</div>\" : \"\") +\n    (!d.guide.bot && !d.guide.fmt && !d.guide.samples.length ? '<div class=\"muted\">Hali yuklanmagan.</div>' : \"\") + \"</div>\";\n  h += '<div class=\"card\"><h3>👨‍🏫 Muallif — ' + esc(d.author) + '</h3><div class=\"muted\">Taklif, savol yoki hamkorlik bo\\'yicha yozing — javob bot chatiga keladi.</div>' +\n    '<textarea id=\"sup\" rows=\"3\" maxlength=\"3000\" placeholder=\"Xabaringiz…\" style=\"margin-top:8px\"></textarea>' +\n    '<div class=\"row\" style=\"gap:8px;margin-top:8px\"><button class=\"btn grow\" id=\"supgo\">📨 Yuborish</button><button class=\"pick alt grow\" style=\"margin:0\" id=\"tgau\">✉️ Telegramda</button></div></div>';\n  if (d.donate) h += '<div class=\"card\"><h3>💝 Qo\\'llab-quvvatlash</h3><div class=\"muted\">Bot bepul ishlaydi. Foydali bo\\'lsa, rivojiga hissa qo\\'shishingiz mumkin — rahmat! 🙏</div>' +\n    '<div style=\"white-space:pre-wrap;margin-top:8px\">' + esc(d.donate).replace(/((?:\\d[ -]?){12,19}\\d?)/g, '<button class=\"chip\" data-copy=\"$1\">📋 $1</button>') + \"</div></div>\";\n  h += '<div class=\"card\"><h3>⚙️ Sozlamalar</h3><label class=\"f\" style=\"margin-top:0\">🌐 Bot tili</label>' +\n    Object.entries(d.lang.langs).map(([k, v]) => '<button class=\"chip' + (d.lang.lang === k ? \" on\" : \"\") + '\" data-lang=\"' + k + '\">' + esc(v) + \"</button>\").join(\"\") +\n    '<button class=\"ghost\" id=\"deld\" style=\"color:var(--danger);width:100%;margin-top:12px\">🗑 Ma\\'lumotlarimni o\\'chirish</button></div>';\n  h += '<div class=\"card\"><h3>💬 Botda</h3><div class=\"muted\">🧰 Fayl vositalari va 📣 Reklama berish — bot chatida.</div>' +\n    '<button class=\"pick alt\" id=\"tobot\">💬 Bot chatiga o\\'tish</button></div>';\n  $app.innerHTML = h; bindHome();\n  const rd = document.getElementById(\"rvdue\"); if (rd) rd.onclick = () => { state.info = { id: \"review\", review: \"due\", title: \"Takrorlash\" }; startPlay(false); };\n  const ra = document.getElementById(\"rvall\"); if (ra) ra.onclick = () => { state.info = { id: \"review\", review: \"all\", title: \"Takrorlash\" }; startPlay(false); };\n  $app.querySelectorAll(\"[data-g]\").forEach((b) => b.onclick = () => sendGuide(b.dataset.g));\n  document.getElementById(\"supgo\").onclick = async () => {\n    const t = document.getElementById(\"sup\").value.trim(); if (!t) return toast(\"Xabar matnini yozing\");\n    try { await api(\"/support\", { text: t }); haptic(\"success\"); document.getElementById(\"sup\").value = \"\"; toast(\"✅ Yuborildi — javob bot chatiga keladi\"); }\n    catch (e) { toast(\"⚠️ \" + e.message); }\n  };\n  const openTg = (u) => (tg && tg.openTelegramLink ? tg.openTelegramLink(u) : window.open(u));\n  document.getElementById(\"tgau\").onclick = () => openTg(\"https://t.me/\" + d.author.replace(/^@/, \"\"));\n  document.getElementById(\"tobot\").onclick = () => { openTg(\"https://t.me/\" + d.bot); try { tg.close(); } catch (e) {} };\n  $app.querySelectorAll(\"[data-copy]\").forEach((b) => b.onclick = async () => {\n    try { await navigator.clipboard.writeText(b.dataset.copy.replace(/\\s/g, \"\")); toast(\"📋 Nusxalandi\"); } catch (e) { toast(b.dataset.copy); }\n  });\n  $app.querySelectorAll(\"[data-lang]\").forEach((b) => b.onclick = async () => { await api(\"/lang\", { code: b.dataset.lang }).catch(() => {}); haptic(\"success\"); toast(\"✅ Bot tili o'zgardi\"); loadMore(); });\n  document.getElementById(\"deld\").onclick = async () => {\n    if (!(await confirmBox(\"Botdagi barcha testlaringiz, natijalaringiz va reytingdagi o'rningiz butunlay o'chiriladi. Davom etaymi?\"))) return;\n    if (!(await confirmBox(\"Rostdan ham? Buni qaytarib bo'lmaydi.\"))) return;\n    try { const r = await api(\"/deldata\", { confirm: \"DELETE\" }); toast(\"✅ O'chirildi: \" + r.quizzes + \" ta test\"); loadCatalog(); } catch (e) { toast(\"⚠️ \" + e.message); }\n  };\n}\n\n// ---------- Boshlash ----------\nif (!tg || !tg.initData) {\n  $app.innerHTML = '<div class=\"empty\">📱 Bu ilova Telegram ichida ishlaydi.<br>Botdagi «📱 Ilova» tugmasi orqali oching.</div>';\n} else {\n  const sp = String(tg.initDataUnsafe.start_param || \"\");\n  const e = location.hash.match(/q=([\\w-]+)/) || sp.match(/^e_([\\w-]+)/);\n  const p = location.hash.match(/p=([\\w-]+)/) || sp.match(/^(?:p_)?([\\w-]{4,})$/);\n  if (e) openQuiz(e[1]); else if (p) openPlay(p[1]); else loadCatalog();\n}\n</script>\n</body>\n</html>\n";
